SELECT base.*,CASE WHEN activity IN ('Goods Receipt Reversed','Invoice Blocked','PO Item Deleted','PO Rejected','Payment Reversed','Quality Inspection Failed','Requisition Rejected','Stock Placed in Blocked Stock','Supplier Blocked','Three-Way Match Failed') THEN 1 ELSE 0 END is_exception_event FROM (WITH all_h AS (SELECT *,0 archived FROM cdhdr UNION ALL SELECT *,1 FROM archive_cdhdr), dedup_h AS (SELECT * FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY change_number ORDER BY archived) rn FROM all_h) WHERE rn=1), all_p AS (SELECT * FROM cdpos UNION ALL SELECT * FROM archive_cdpos), scope_refs AS (SELECT predecessor_id scope_key,json_group_array(successor_id) object_refs FROM document_flow WHERE relation_code='OBJECT_SCOPE' GROUP BY predecessor_id), changes AS (SELECT h.change_number source_record_id,h.object_id scope_key,MAX(CASE WHEN p.field_name LIKE 'PC%' THEN p.field_name END) technical_code,substr(h.change_date,1,4)||'-'||substr(h.change_date,5,2)||'-'||substr(h.change_date,7,2)||'T'||substr(h.change_time,1,2)||':'||substr(h.change_time,3,2)||':'||substr(h.change_time,5,2)||'Z' timestamp,h.username actor,sr.object_refs,'cdhdr' source_table FROM dedup_h h JOIN all_p p USING(client,object_class,object_id,change_number) JOIN scope_refs sr ON sr.scope_key=h.object_id GROUP BY h.change_number,h.object_id,h.change_date,h.change_time,h.username,sr.object_refs), mapped_changes AS (SELECT *,CASE technical_code WHEN 'PC001' THEN 'Purchase Requisition Created' WHEN 'PC002' THEN 'Requisition Item Added' WHEN 'PC003' THEN 'Requisition Item Changed' WHEN 'PC004' THEN 'Requisition Submitted' WHEN 'PC005' THEN 'Requisition Released' WHEN 'PC006' THEN 'Requisition Rejected' WHEN 'PC007' THEN 'RFQ Created' WHEN 'PC008' THEN 'RFQ Sent' WHEN 'PC009' THEN 'Supplier Quotation Received' WHEN 'PC010' THEN 'Quotation Revised' WHEN 'PC011' THEN 'Quotation Evaluated' WHEN 'PC012' THEN 'Source Selected' WHEN 'PC013' THEN 'Contract Referenced' WHEN 'PC014' THEN 'Requisition Converted to PO' WHEN 'PC015' THEN 'Purchase Order Created' WHEN 'PC016' THEN 'PO Item Added' WHEN 'PC017' THEN 'PO Quantity Changed' WHEN 'PC018' THEN 'PO Price Changed' WHEN 'PC019' THEN 'Delivery Date Changed' WHEN 'PC020' THEN 'PO Submitted for Approval' WHEN 'PC021' THEN 'PO Released' WHEN 'PC022' THEN 'PO Rejected' WHEN 'PC023' THEN 'PO Sent to Supplier' WHEN 'PC024' THEN 'Supplier Confirmation Received' WHEN 'PC025' THEN 'Supplier Confirmation Changed' WHEN 'PC026' THEN 'Advance Shipping Notice Received' WHEN 'PC027' THEN 'PO Item Deleted' WHEN 'PC028' THEN 'Goods Receipt Posted' WHEN 'PC029' THEN 'Goods Receipt Reversed' WHEN 'PC030' THEN 'Partial Receipt Posted' WHEN 'PC031' THEN 'Quality Inspection Started' WHEN 'PC032' THEN 'Quality Inspection Passed' WHEN 'PC033' THEN 'Quality Inspection Failed' WHEN 'PC034' THEN 'Stock Placed in Blocked Stock' WHEN 'PC035' THEN 'Stock Released from Blocked Stock' WHEN 'PC036' THEN 'Return to Supplier Posted' WHEN 'PC037' THEN 'PO Item Delivery Completed' WHEN 'PC038' THEN 'Invoice Received' WHEN 'PC039' THEN 'Invoice Parked' WHEN 'PC040' THEN 'Invoice Posted' WHEN 'PC041' THEN 'Invoice Changed' WHEN 'PC042' THEN 'Three-Way Match Passed' WHEN 'PC043' THEN 'Three-Way Match Failed' WHEN 'PC044' THEN 'Invoice Blocked' WHEN 'PC045' THEN 'Invoice Unblocked' WHEN 'PC046' THEN 'Credit Memo Posted' WHEN 'PC047' THEN 'Accounting Document Created' WHEN 'PC048' THEN 'Payment Proposal Created' WHEN 'PC049' THEN 'Payment Proposal Approved' WHEN 'PC050' THEN 'Payment Executed' WHEN 'PC051' THEN 'Payment Reversed' WHEN 'PC052' THEN 'PO Item Final-Invoiced' WHEN 'PC053' THEN 'Purchase Order Closed' WHEN 'PC054' THEN 'Supplier Blocked' WHEN 'PC055' THEN 'Supplier Unblocked' END activity FROM changes), apps AS (SELECT record_key source_record_id, document_ref scope_key, document_code, substr(posting_date,1,4)||'-'||substr(posting_date,5,2)||'-'||substr(posting_date,7,2)||'T'||substr(posting_time,1,2)||':'||substr(posting_time,3,2)||':'||substr(posting_time,5,2)||'Z' timestamp, username actor, related_refs_json object_refs, 'req_header' source_table FROM req_header UNION ALL SELECT record_key source_record_id, document_ref scope_key, document_code, substr(posting_date,1,4)||'-'||substr(posting_date,5,2)||'-'||substr(posting_date,7,2)||'T'||substr(posting_time,1,2)||':'||substr(posting_time,3,2)||':'||substr(posting_time,5,2)||'Z' timestamp, username actor, related_refs_json object_refs, 'goods_movement_header' source_table FROM goods_movement_header UNION ALL SELECT record_key source_record_id, document_ref scope_key, document_code, substr(posting_date,1,4)||'-'||substr(posting_date,5,2)||'-'||substr(posting_date,7,2)||'T'||substr(posting_time,1,2)||':'||substr(posting_time,3,2)||':'||substr(posting_time,5,2)||'Z' timestamp, username actor, related_refs_json object_refs, 'inspection_lot' source_table FROM inspection_lot UNION ALL SELECT record_key source_record_id, document_ref scope_key, document_code, substr(posting_date,1,4)||'-'||substr(posting_date,5,2)||'-'||substr(posting_date,7,2)||'T'||substr(posting_time,1,2)||':'||substr(posting_time,3,2)||':'||substr(posting_time,5,2)||'Z' timestamp, username actor, related_refs_json object_refs, 'invoice_header' source_table FROM invoice_header UNION ALL SELECT record_key source_record_id, document_ref scope_key, document_code, substr(posting_date,1,4)||'-'||substr(posting_date,5,2)||'-'||substr(posting_date,7,2)||'T'||substr(posting_time,1,2)||':'||substr(posting_time,3,2)||':'||substr(posting_time,5,2)||'Z' timestamp, username actor, related_refs_json object_refs, 'accounting_header' source_table FROM accounting_header UNION ALL SELECT record_key source_record_id, document_ref scope_key, document_code, substr(posting_date,1,4)||'-'||substr(posting_date,5,2)||'-'||substr(posting_date,7,2)||'T'||substr(posting_time,1,2)||':'||substr(posting_time,3,2)||':'||substr(posting_time,5,2)||'Z' timestamp, username actor, related_refs_json object_refs, 'payment_run' source_table FROM payment_run), mapped_apps AS (SELECT *,CASE document_code WHEN 'PC001' THEN 'Purchase Requisition Created' WHEN 'PC002' THEN 'Requisition Item Added' WHEN 'PC003' THEN 'Requisition Item Changed' WHEN 'PC004' THEN 'Requisition Submitted' WHEN 'PC005' THEN 'Requisition Released' WHEN 'PC006' THEN 'Requisition Rejected' WHEN 'PC007' THEN 'RFQ Created' WHEN 'PC008' THEN 'RFQ Sent' WHEN 'PC009' THEN 'Supplier Quotation Received' WHEN 'PC010' THEN 'Quotation Revised' WHEN 'PC011' THEN 'Quotation Evaluated' WHEN 'PC012' THEN 'Source Selected' WHEN 'PC013' THEN 'Contract Referenced' WHEN 'PC014' THEN 'Requisition Converted to PO' WHEN 'PC015' THEN 'Purchase Order Created' WHEN 'PC016' THEN 'PO Item Added' WHEN 'PC017' THEN 'PO Quantity Changed' WHEN 'PC018' THEN 'PO Price Changed' WHEN 'PC019' THEN 'Delivery Date Changed' WHEN 'PC020' THEN 'PO Submitted for Approval' WHEN 'PC021' THEN 'PO Released' WHEN 'PC022' THEN 'PO Rejected' WHEN 'PC023' THEN 'PO Sent to Supplier' WHEN 'PC024' THEN 'Supplier Confirmation Received' WHEN 'PC025' THEN 'Supplier Confirmation Changed' WHEN 'PC026' THEN 'Advance Shipping Notice Received' WHEN 'PC027' THEN 'PO Item Deleted' WHEN 'PC028' THEN 'Goods Receipt Posted' WHEN 'PC029' THEN 'Goods Receipt Reversed' WHEN 'PC030' THEN 'Partial Receipt Posted' WHEN 'PC031' THEN 'Quality Inspection Started' WHEN 'PC032' THEN 'Quality Inspection Passed' WHEN 'PC033' THEN 'Quality Inspection Failed' WHEN 'PC034' THEN 'Stock Placed in Blocked Stock' WHEN 'PC035' THEN 'Stock Released from Blocked Stock' WHEN 'PC036' THEN 'Return to Supplier Posted' WHEN 'PC037' THEN 'PO Item Delivery Completed' WHEN 'PC038' THEN 'Invoice Received' WHEN 'PC039' THEN 'Invoice Parked' WHEN 'PC040' THEN 'Invoice Posted' WHEN 'PC041' THEN 'Invoice Changed' WHEN 'PC042' THEN 'Three-Way Match Passed' WHEN 'PC043' THEN 'Three-Way Match Failed' WHEN 'PC044' THEN 'Invoice Blocked' WHEN 'PC045' THEN 'Invoice Unblocked' WHEN 'PC046' THEN 'Credit Memo Posted' WHEN 'PC047' THEN 'Accounting Document Created' WHEN 'PC048' THEN 'Payment Proposal Created' WHEN 'PC049' THEN 'Payment Proposal Approved' WHEN 'PC050' THEN 'Payment Executed' WHEN 'PC051' THEN 'Payment Reversed' WHEN 'PC052' THEN 'PO Item Final-Invoiced' WHEN 'PC053' THEN 'Purchase Order Closed' WHEN 'PC054' THEN 'Supplier Blocked' WHEN 'PC055' THEN 'Supplier Unblocked' END activity FROM apps), all_events AS (SELECT * FROM mapped_changes UNION ALL SELECT source_record_id,scope_key,document_code,timestamp,actor,object_refs,source_table,activity FROM mapped_apps) SELECT f.predecessor_id case_id,e.activity,e.timestamp,e.source_table,e.source_record_id,e.actor,e.object_refs FROM all_events e JOIN document_flow f ON f.successor_id=e.scope_key AND f.relation_code='FOLLOW_ON' WHERE activity IS NOT NULL ORDER BY case_id,timestamp,source_record_id) base ORDER BY case_id,timestamp,source_record_id;
